#include "../src/rendering/text/real_font_metrics.h"
#include "../src/rendering/text/truetype_raster.h"
#include <fstream>
#include <iostream>
using namespace aether::rendering::text;
namespace tt=aether::rendering::text::truetype;
int main(int argc,char**){bool document=argc>1;for(const char*name:{"DejaVuSans.ttf","DejaVuSans-Bold.ttf"}){std::ifstream in(std::string("/usr/share/fonts/truetype/dejavu/")+name,std::ios::binary);auto source=std::make_shared<const FontSource>(std::vector<uint8_t>((std::istreambuf_iterator<char>(in)),{}));for(int size:{16,24}){auto binding=std::get<std::shared_ptr<const tt::RealFontBinding>>(tt::RealFontBinding::create(source,size*64,tt::q1_unhinted));for(unsigned cp:{32,65,66,103,109,64}){auto gid=std::get<tt::Mapped>(binding->map()->lookup(cp)).glyph_id;auto outline=std::get<std::shared_ptr<const tt::Outline>>(binding->face()->outline(gid));for(unsigned phase:{0,1,31,63})for(unsigned py:{0,1,31,63}){tt::RasterWork work;tt::AggregateBudget raster{512000000},bytes{64*1024*1024};auto result=document?tt::rasterize_document_budgeted(outline,binding->font(),phase,py,raster,bytes,nullptr,&work):tt::rasterize_budgeted(outline,binding->font(),phase,py,raster,bytes,nullptr,&work);std::cout<<name<<","<<size<<","<<cp<<","<<phase<<","<<py;if(auto*error=std::get_if<tt::RasterError>(&result)){std::cout<<",ERROR="<<int(*error)<<"\n";return 1;}auto mask=std::get<tt::RasterOutput>(result).mask;std::cout<<","<<mask->width<<","<<mask->height<<","<<detail::sha256(std::string_view((const char*)mask->bytes.data(),mask->bytes.size()))<<",reserved="<<work.aggregate_charged<<",units="<<work.units<<"\n";}}}}}
